  don_live: "<strong style=\"color:var(--green)\">\u0421\u0435\u0433\u0430 \u0434\u043E\u0441\u0442\u0430\u043F\u043D\u043E:</strong> 250 \u043C\u043E\u043D\u0435\u0442\u0438 \u00B7 \u0442\u043E\u043A\u0435\u043D\u0438\u0437\u0438\u0440\u0430\u043D\u0438 \u0430\u043A\u0446\u0438\u0438 \u00B7 \u043F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0434\u0443\u0432\u0430\u045A\u0430 \u0437\u0430 \u0441\u043E\u043F\u0441\u0442\u0432\u0435\u043D\u0438\u0446\u0438\u0442\u0435 \u00B7 \u0458\u0430\u0432\u043D\u0430 \u0435\u0432\u0438\u0434\u0435\u043D\u0446\u0438\u0458\u0430 \u00B7 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u0435\u043D API",
