  pro_active_sub_1: ' \u0441\u0435 \u043F\u0440\u0438\u0434\u0440\u0443\u0436\u0438\u0458\u0430 \u043F\u0440\u0435\u043A\u0443 \u0432\u0430\u0448\u0438\u043E\u0442 \u043B\u0438\u043D\u043A. \u041F\u043E\u043C\u0430\u0433\u0430\u0442\u0435 Rotator \u0434\u0430 \u043E\u0441\u0442\u0430\u043D\u0435 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u0435\u043D \u0437\u0430 \u0441\u0438\u0442\u0435 \u2014 \u0432\u0438 \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u0438\u043C\u0435!',
