/* ── Helper: get translated string ───────────────────────────── */
function t(key) {
  var lang = (typeof currentLang !== 'undefined') ? currentLang : 'en';
  var dict = I18N[lang] || I18N.en;
  return (dict[key] !== undefined) ? dict[key] : (I18N.en[key] || key);
}

/* ── Apply language to all translatable sections ─────────────── */
function applyLang() {
  var lang = (typeof currentLang !== 'undefined') ? currentLang : 'en';
  var s = I18N[lang] || I18N.en;

  /* ── FAQ modal ── */
  var faqTitle = document.querySelector('#faq-modal .modal-title');
  var faqSub   = document.querySelector('#faq-modal .modal-sub');
  if (faqTitle) faqTitle.innerHTML = '\u2753 ' + s.faq_title;
  if (faqSub)   faqSub.textContent = s.faq_sub;

  var faqItems = document.querySelectorAll('#faq-modal .faq-item');
  if (faqItems.length && s.faq) {
    for (var i = 0; i < faqItems.length && i < s.faq.length; i++) {
      var q = faqItems[i].querySelector('.faq-q');
      var a = faqItems[i].querySelector('.faq-a');
      if (q) q.textContent = s.faq[i].q;
      if (a) a.textContent = s.faq[i].a;
    }
  }

  /* ── Donate modal ── */
  var donTitle = document.querySelector('#donate-modal .modal-title');
  var donSub   = document.querySelector('#donate-modal .modal-sub');
  if (donTitle) donTitle.innerHTML = s.don_title;
  if (donSub)   donSub.innerHTML   = s.don_sub;

  var donBuilds = document.querySelector('#donate-modal [style*="letter-spacing:.14em"]');
  if (donBuilds) donBuilds.textContent = s.don_builds;

  /* Guarded per line, 2026-09-25 (promptove/66). The donate modal's
     layout had changed, this selector matched divs with no span, and the
     TypeError aborted applyLang() here, so everything below (the Pro tile,
     both tutorials, the share label) silently stayed in English for
     anyone who chose Macedonian. A missing element now skips one line,
     never the rest of the language. */
  var donItems = document.querySelectorAll('#donate-modal .modal > div:nth-child(4) > div > div');
  [s.don_live, s.don_next, s.don_road].forEach(function(html, k) {
    var span = donItems[k] && donItems[k].querySelector('span:last-child');
    if (span) span.innerHTML = html;
  });

  var netTag = document.querySelector('#donate-modal .network-tag');
  if (netTag) netTag.textContent = s.don_net;

  var copyDon = document.getElementById('copy-donate-btn');
  if (copyDon && !copyDon.classList.contains('ok')) copyDon.textContent = s.don_copy;

  var donNote = document.querySelector('#donate-modal .modal-note');
  if (donNote) donNote.innerHTML = s.don_note;

  /* ── Keep it Free tile (sidebar) ── */
  var keepTitle = document.querySelector('.sidebar-donate .ad-donate-title');
  var keepSub   = document.querySelector('.sidebar-donate .ad-donate-sub');
  var keepBtn   = document.querySelector('.sidebar-donate .ad-donate-btn');
  if (keepTitle) keepTitle.textContent = s.keep_title;
  if (keepSub)   keepSub.innerHTML     = s.keep_sub;
  if (keepBtn)   keepBtn.textContent   = s.keep_btn;

  /* ── Unlock Pro tile (right panel) ── */
  var proTitle = document.querySelector('.ad-promo-title');
  var proSub   = document.querySelector('.ad-promo-sub');
  var proBtn   = document.querySelector('.ad-promo-btn');
  if (proTitle) proTitle.textContent = s.pro_tile_title;
  if (proSub)   proSub.innerHTML     = s.pro_tile_sub;
  if (proBtn)   proBtn.textContent   = s.pro_tile_btn;

  var feats = document.querySelectorAll('.ad-promo-feat div');
  var featKeys = ['pro_feat_1','pro_feat_2','pro_feat_3','pro_feat_4'];
  for (var i = 0; i < feats.length && i < featKeys.length; i++) {
    feats[i].innerHTML = '<span>\u25B8</span>' + s[featKeys[i]];
  }

  /* ── Tutorial steps ──
     Structured plain-text fields (title, p, note, warn, opts, agreeText),
     turned into markup by _tutDesc() in tutorial.js. A language without a
     tut entry falls back to the English snapshot TUT_EN, so switching
     back to English restores it instead of leaving the last language. */
  var tutSrc = s.tut || (typeof TUT_EN !== 'undefined' ? TUT_EN : null);
  if (tutSrc && typeof TUT_STEPS !== 'undefined' && (typeof proTutOrigSteps === 'undefined' || !proTutOrigSteps)) {
    ['title', 'p', 'note', 'warn', 'opts', 'agreeText'].forEach(function(k) {
      for (var i = 0; i < TUT_STEPS.length && i < tutSrc.length; i++) {
        if (tutSrc[i][k] !== undefined) TUT_STEPS[i][k] = tutSrc[i][k];
      }
    });
    if (typeof tutActive !== 'undefined' && tutActive) tutRender();
  }

  /* ── Swap tutorial steps ── same fallback, to SWAP_EN in ui.js */
  var swapSrc = s.swap_tut || (typeof SWAP_EN !== 'undefined' ? SWAP_EN : null);
  if (swapSrc && typeof SWAP_TUT_STEPS !== 'undefined') {
    for (var i = 0; i < SWAP_TUT_STEPS.length && i < swapSrc.length; i++) {
      SWAP_TUT_STEPS[i].title = swapSrc[i].title;
      SWAP_TUT_STEPS[i].desc  = swapSrc[i].desc;
    }
  }

  /* ── Share button label ── */
  var shareLabel = document.querySelector('.td-share-label');
  if (shareLabel) shareLabel.textContent = s.share_label;
}
